"""Aho-Corasick multi-pattern matching algorithm."""

from collections import deque


class TrieNode:
    __slots__ = ("children", "fail", "output")

    def __init__(self):
        self.children: dict[str, "TrieNode"] = {}
        self.fail: "TrieNode | None" = None
        self.output: list[str] = []


class AhoCorasick:
    def __init__(self, patterns: list[str] | None = None):
        self.root = TrieNode()
        self._built = False
        if patterns:
            for p in patterns:
                self.add(p)
            self.build()

    def add(self, pattern: str) -> None:
        node = self.root
        for ch in pattern:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.output.append(pattern)
        self._built = False

    def build(self) -> None:
        queue: deque[TrieNode] = deque()
        self.root.fail = self.root
        for child in self.root.children.values():
            child.fail = self.root
            queue.append(child)

        while queue:
            current = queue.popleft()
            for ch, child in current.children.items():
                queue.append(child)
                fallback = current.fail
                while fallback is not self.root and ch not in fallback.children:
                    fallback = fallback.fail
                child.fail = fallback.children.get(ch, self.root)
                if child.fail is child:
                    child.fail = self.root
                child.output = child.output + child.fail.output

        self._built = True

    def search(self, text: str) -> list[tuple[int, str]]:
        if not self._built:
            self.build()

        results: list[tuple[int, str]] = []
        node = self.root

        for i, ch in enumerate(text):
            while node is not self.root and ch not in node.children:
                node = node.fail
            node = node.children.get(ch, self.root)
            for pattern in node.output:
                results.append((i - len(pattern) + 1, pattern))

        return results

    def contains_any(self, text: str) -> bool:
        if not self._built:
            self.build()

        node = self.root
        for ch in text:
            while node is not self.root and ch not in node.children:
                node = node.fail
            node = node.children.get(ch, self.root)
            if node.output:
                return True
        return False
